         color: var(--text-muted);\n            margin: 2px 0;\n        }\n\n        /* Summary Cards */\n        .stats-grid {\n            display: grid;\n            grid-template-columns: repeat(4, 1fr);\n            gap: 20px;\n            margin-bottom: 40px;\n        }\n\n        .stat-card {\n            background: var(--bg-light);\n            padding: 20px;\n            border-radius: 12px;\n            text-align: center;\n        }\n\n        .stat-value {\n            font-size: 28px;\n            font-weight: 800;\n            color: var(--primary);\n            display: block;\n        }\n\n        .stat-label {\n            font-size: 11px;\n            font-weight: 700;\n            color: var(--text-muted);\n            text-transform: uppercase;\n            margin-top: 5px;\n            display: block;\n        }\n\n        /* Distribution Section */\n        .section-title {\n            font-size: 16px;\n            font-weight: 700;\n            color: var(--primary);\n            margin-bottom: 20px;\n            padding-left: 10px;\n            border-left: 4px solid var(--accent);\n        }\n\n        .dist-grid {\n            display: grid;\n            grid-template-columns: repeat(3, 1fr);\n            gap: 15px;\n            margin-bottom: 40px;\n        }\n\n        .dist-item {\n            border: 1px solid #e2e8f0;\n            padding: 15px;\n            border-radius: 10px;\n            display: flex;\n            align-items: center;\n        }\n\n        .dist-dot {\n            width: 12px;\n            height: 12px;\n            border-radius: 50%;\n            margin-right: 12px;\n        }\n\n        .dot-green { background-color: var(--success); }\n        .dot-yellow { background-color: var(--warning); }\n        .dot-red { background-color: var(--danger); }\n\n        .dist-info {\n            flex-grow: 1;\n        }\n\n        .dist-name {\n            font-size: 12px;\n            font-weight: 600;\n            color: var(--text-muted);\n        }\n\n        .dist-val {\n            font-size: 18px;\n            font-weight: 700;\n            color: var(--primary);\n        }\n\n        /* Table */\n        table {\n            width: 100%;\n            border-collapse: collapse;\n            margin-bottom: 40px;\n        }\n\n        th {\n            background-color: var(--primary);\n            color: white;\n            font-size: 11px;\n            text-transform: uppercase;\n            text-align: left;\n            padding: 12px 15px;\n        }\n\n        td {\n            padding: 12px 15px;\n            font-size: 13px;\n            border-bottom: 1px solid #e2e8f0;\n        }\n\n        .badge {\n            padding: 4px 8px;\n            border-radius: 4px;\n            font-size: 10px;\n            font-weight: 700;\n            text-transform: uppercase;\n        }\n\n        .bg-red { background: #fee2e2; color: #991b1b; }\n        .bg-yellow { background: #fef3c7; color: #92400e; }\n        .bg-green { background: #d1fae5; color: #065f46; }\n\n        /* Recommendations */\n        .analysis-box {\n            background-color: var(--bg-light);\n            border-radius: 12px;\n            padding: 25px;\n            margin-bottom: 40px;\n            display: grid;\n            grid-template-columns: 1fr 1fr;\n            gap: 30px;\n        }\n\n        .analysis-title {\n            font-size: 14px;\n            font-weight: 700;\n            margin-bottom: 15px;\n            color: var(--primary);\n        }\n\n        .analysis-list {\n            margin: 0;\n            padding-left: 20px;\n            font-size: 13px;\n            color: var(--text-main);\n        }\n\n        .analysis-list li {\n            margin-bottom: 8px;\n        }\n\n        /* Signatures */\n        .signatures {\n            display: flex;\n            justify-content: space-between;\n            margin-top: 80px;\n            page-break-inside: avoid;\n        }\n\n        .